Translate("esMX", "rau-cliffrunner", {
	title = "Rau Cliffrunner",
	subtitle = "Buscador de la Cloven Hoof",
	found = "Poblado Viento Libre",
	hint = [=[Hable con el tauren del Poblado Viento Libre que estudia a los centauros.]=],
	allegiance = "Horda · Poblado Viento Libre",
	aliases = { "Rau" },
	sections = {
		{
			title = "Resumen",
			text = [=[Rau Cliffrunner es un {link:tauren}tauren{/link} del {link:freewind-post}Poblado Viento Libre{/link} que quiere comprender a los centauros, no solo combatirlos. Con su socio Zangen Stonehoof, de {link:thunder-bluff}Cima del Trueno{/link}, se propuso hacerse con la Cloven Hoof, una reliquia que los Galak guardan desde el tiempo en que fue creado su pueblo.]=],
		},
		{
			title = "Importancia",
			text = [=[Rau encontró la clave de las defensas de los centauros en su propia ascendencia. Como las dríades y los centauros comparten un origen común, el agua de un pozo de la luna de los elfos de la noche podía vencer la llama eterna que guardaba la reliquia.]=],
