			text = [=[El agua del pozo de la luna solo apagaría la llama del {link:splithoof-crag}Campamento Pezuña Quebrada{/link} durante un breve tiempo. Fue suficiente. La Cloven Hoof salió de la fortaleza de los centauros, y Rau sintió una extraña energía moviéndose en su interior. Cree que revelará a los {link:tauren}tauren{/link} cosas sorprendentes sobre los centauros, y ha empezado a descifrarla.]=],
		},
	},
	mentions = {
		{ text = "La llama sagrada" },
		{ text = "La llama sagrada, la Cloven Hoof" },
