	bonds = {
		{ id = "zangen-stonehoof", name = "Zangen Stonehoof", note = "su socio en Cima del Trueno" },
	},
})

Translate("esMX", "motega-firemane", {
	title = "Motega Firemane",
	subtitle = "Guardián del Campamento del Tramo Blanco",
	found = "Campamento del Tramo Blanco",
	hint = [=[Hable con el tauren que estudia las criaturas de las Agujas en el Campamento del Tramo Blanco.]=],
	allegiance = "Horda · Campamento del Tramo Blanco",
	aliases = { "Motega" },
	sections = {
		{
			title = "Resumen",
			text = [=[Motega Firemane vino a {link:thousand-needles}Las Mil Agujas{/link} a estudiar las criaturas que viven allí, y trajo consigo al joven {link:pao-ka-swiftmountain}Pao'ka Swiftmountain{/link}. Tiene sus tiendas en el {link:whitereach-post}Campamento del Tramo Blanco{/link}, en el noroeste del cañón. Motega conoce los viejos relatos de los {link:tauren}tauren{/link} mejor que la mayoría, y cuando una serpiente de leyenda regresó a las Agujas, fue a él a quien acudieron los tauren.]=],
		},
		{
			title = "Importancia",
			text = [=[Motega es el puente entre {link:thousand-needles}las Agujas{/link} y la anciana bruja. Fue él quien avisó a {link:magatha-grimtotem}Magatha Grimtotem{/link} de la serpiente {link:arikara}Arikara{/link}, y quien recibió el polvo que la haría surgir del fuego sagrado. Fue también el primero en encontrar extraña su advertencia.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Estudia las criaturas de {link:thousand-needles}Las Mil Agujas{/link} desde el {link:whitereach-post}Campamento del Tramo Blanco{/link}.
• Cuida de {link:pao-ka-swiftmountain}Pao'ka Swiftmountain{/link}, cuyo padre se resistía a dejar venir al muchacho.
• Conoce la leyenda de {link:arikara}Arikara{/link}, la serpiente nacida para vengar los actos atroces.
• Pidió la ayuda de {link:magatha-grimtotem}Magatha{/link} para avivar el fuego sagrado latente de la {link:darkcloud-pinnacle}Cumbre de la Nube Negra{/link}.]=],
		},
		{
			title = "Sin registro",
			text = [=[Poco se ha escrito de la vida de Motega antes del {link:whitereach-post}Campamento del Tramo Blanco{/link}. No consta quién es el padre de {link:pao-ka-swiftmountain}Pao'ka{/link} ni por qué confió el muchacho a Motega.]=],
		},
	},
	chapters = {
		{
			title = "El muchacho perdido",
			hint = "Traiga a Pao'ka a casa desde Nido Alto.",
			text = [=[{link:pao-ka-swiftmountain}Pao'ka{/link} entró solo en {link:highperch}Nido Alto{/link} para estudiar a los dracoleones y no volvió. Cuando por fin trajeron al muchacho a casa, Motega estaba furioso. Dijo que, de haberlo sabido, lo habría encadenado a un tótem. Bajo el enfado había gratitud, y recompensó a quienes habían ayudado.]=],
		},
		{
			title = "La leyenda de Arikara",
			hint = "Responda a la advertencia de Hagar Lightninghoof.",
			text = [=[Motega había oído hablar de {link:arikara}Arikara{/link} toda su vida y nunca creyó que llegaría a verla. Ahora la leyenda era cierta. Para cazar a la serpiente había que encender el fuego sagrado de la vida de la {link:darkcloud-pinnacle}Cumbre de la Nube Negra{/link}, y solo un chamán poderoso podía encantar el raro agave Incendia que lo encendería. Motega envió el agave recogido a {link:magatha-grimtotem}Magatha Grimtotem{/link} en {link:thunder-bluff}Cima del Trueno{/link}.]=],
		},
		{
			title = "Una respuesta inquietante",
			hint = "Mate a Arikara y vuelva al Campamento del Tramo Blanco.",
			text = [=[La anciana bruja había advertido que {link:arikara}Arikara{/link} podría estar acechando a {link:cairne-bloodhoof}Cairne Bloodhoof{/link}, enfurecida porque había cambiado demasiado el antiguo saber de los {link:tauren}tauren{/link}. Cuando la serpiente murió, Motega negó con la cabeza. No le parecía lógico que Arikara fuera a cazar al Gran Jefe. Aun así, no quiso decir que {link:magatha-grimtotem}Magatha{/link} se equivocaba. Ella era, dijo, la más poderosa de todos ellos.]=],
		},
	},
	mentions = {
		{ text = "De vuelta a casa" },
		{ text = "Serpiente salvaje" },
		{ text = "Fuego sagrado" },
		{ text = "{link:arikara}Arikara{/link}" },
	},
	bonds = {
		{ id = "pao-ka-swiftmountain", name = "Pao'ka Swiftmountain", note = "el muchacho a su cargo" },
		{ id = "hagar-lightninghoof", name = "Hagar Lightninghoof", note = "le trajo la noticia" },
		{ id = "magatha-grimtotem", name = "Magatha Grimtotem", note = "encantó el polvo" },
		{ id = "arikara", name = "Arikara", note = "la serpiente de leyenda" },
		{ id = "kanati-greycloud", name = "Kanati Greycloud", note = "comparte el Campamento del Tramo Blanco" },
	},
})

