			title = "Resumen",
			text = [=[Arnak es un proscrito del {link:grimtotem-clan}clan Tótem Siniestro{/link}, buscado en el {link:freewind-post}Poblado Viento Libre{/link} por asesinato y rapto. Pidió a {link:lakota-windsong}Lakota Windsong{/link} que fuera su compañera, y ella lo rechazó. Esa misma noche volvió y se la llevó por la fuerza. El hermano de ella intentó detenerlo, y Arnak lo mató. Después llevó a Lakota a la {link:darkcloud-pinnacle}Cumbre de la Nube Negra{/link}.]=],
		},
		{
			title = "Importancia",
			text = [=[Los crímenes de Arnak despertaron la ira de todo el {link:freewind-post}Poblado Viento Libre{/link}. El {link:cliffwatcher-longhorn}Vigiarrisco Cuernolargo{/link} temía que nunca llegara a rendir cuentas ante la justicia, y dijo que las noticias de sus actos le hacían hervir la sangre.]=],
		},
	},
	mentions = {
		{ text = "Se busca: Arnak Grimtotem" },
		{ text = "Libre por fin" },
	},
	bonds = {
		{ id = "lakota-windsong", name = "Lakota Windsong", note = "la mujer a la que raptó" },
		{ id = "cliffwatcher-longhorn", name = "Vigiarrisco Cuernolargo", note = "puso precio a su cabeza" },
	},
})

Translate("esMX", "lakota-windsong", {
