Translate("esMX", "dorn-plainstalker", {
	title = "Dorn Plainstalker",
	subtitle = "El que pone a prueba a los jóvenes",
	found = "Una altura solitaria al nordeste del Poblado Viento Libre",
	hint = [=[Busque al tauren que pone a prueba a los jóvenes en una altura solitaria sobre las Agujas.]=],
	allegiance = "Horda",
	aliases = { "Dorn" },
	sections = {
		{
			title = "Resumen",
			text = [=[Dorn Plainstalker vive solo en una altura sobre {link:thousand-needles}las Agujas{/link}, lejos del bullicio del {link:freewind-post}Poblado Viento Libre{/link}. Considera su deber preparar a los jóvenes de todas las tribus para los peligros que encontrarán cuando dejen la seguridad del hogar. Los pone a prueba en tres cosas: el espíritu, el cuerpo y la mente. Quienes superan las pruebas vuelven más fuertes. Quienes fracasan, dice, aprenden lo vasto que es de verdad el mundo.]=],
		},
		{
			title = "Importancia",
			text = [=[Dorn es un maestro de los de antes. No le importa de qué tribu venga un guerrero, solo si está preparado. Sus pruebas unen a varios de los sabios de la {link:horde}Horda{/link} por todo {link:kalimdor}Kalimdor{/link} y más allá.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Pone a prueba la fe, la resistencia, la fuerza y el saber de los jóvenes.
• Los envía contra la matriarca de las arpías de la {link:roguefeather-den}Guarida Malapluma{/link} y contra el elemental {link:rok-alim-the-pounder}Rok'Alim{/link}.
• Los envía ante el chamán {link:braug-dimspirit}Braug Dimspirit{/link} en la {link:stonetalon-mountains}Sierra Espolón{/link} para la prueba del saber.]=],
		},
		{
			title = "Sin registro",
			text = [=[Poco se ha escrito de la vida de Dorn o de cuánto tiempo lleva en su altura. No se nombra su tribu.]=],
		},
	},
	chapters = {
		{
			title = "El salto de fe",
			hint = "Demuestre su fe en la altura de Dorn.",
			text = [=[La primera prueba de Dorn es la más extraña. Pide a los jóvenes que salten de las tablas de su altura al vacío, sin ninguna promesa de que vivirán. La fe, enseña, importa más de lo que muchos creen. No siempre importa en qué se cree, sino que se crea en algo.]=],
		},
		{
			title = "Cuerpo y fuerza",
			hint = "Supere las pruebas de resistencia y de fuerza.",
			text = [=[Para el cuerpo, Dorn envía a los jóvenes a la {link:roguefeather-den}Guarida Malapluma{/link} a echar a perder las provisiones de las arpías y a enfrentarse a {link:grenka-bloodscreech}Grenka Bloodscreech{/link} cuando llega llena de furia. Para la fuerza, los envía contra {link:rok-alim-the-pounder}Rok'Alim{/link}, un elemental que ha permanecido en {link:thousand-needles}las Agujas{/link} desde la era de los Dioses Antiguos.]=],
		},
		{
			title = "El paso final",
			hint = "Complete la prueba del saber y vuelva con Dorn.",
			text = [=[La prueba del saber no le corresponde a él. Pasa por {link:braug-dimspirit}Braug Dimspirit{/link} en la {link:stonetalon-mountains}Sierra Espolón{/link} y va más allá, hasta eruditos lejos de {link:thousand-needles}las Agujas{/link}. Cuando por fin los jóvenes vuelven con Dorn, él los mira como si hubieran pasado muchas lunas desde su primer salto, y les dice que su mente, su cuerpo y su espíritu son fuertes.]=],
		},
	},
	mentions = {
		{ text = "Prueba de fe" },
		{ text = "Prueba de resistencia" },
		{ text = "Prueba de fuerza" },
		{
			text = [=[Prueba de saber, el camino hacia {link:braug-dimspirit}Braug Dimspirit{/link}]=],
		},
		{ text = "Paso final" },
	},
	bonds = {
		{ id = "grenka-bloodscreech", name = "Grenka Bloodscreech", note = "la prueba de resistencia" },
		{ id = "rok-alim-the-pounder", name = "Rok'Alim el Machacador", note = "la prueba de fuerza" },
		{ id = "prate-cloudseer", name = "Prate Cloudseer", note = "vive cerca de su altura" },
		{ id = "braug-dimspirit", name = "Braug Dimspirit", note = "da la prueba del saber" },
	},
})

