Translate("esMX", "moktar-krin", {
	title = "Moktar Krin",
	subtitle = "Líder de un grupo de guerra diezmado",
	found = "La frontera norte de El Desierto de Sal",
	hint = [=[Busque al orco que mantiene un campamento de guerra en la frontera de El Desierto de Sal.]=],
