	aliases = { "Moktar" },
	sections = {
		{
			title = "Resumen",
			text = [=[Moktar Krin dirigió un grupo de guerra de la {link:horde}Horda{/link} para expulsar de {link:the-shimmering-flats}El Desierto de Sal{/link} a los enanos de la {link:explorers-league}Liga de Expedicionarios{/link}. Los enanos murieron, pero durante la lucha un enjambre de insectos brotó de una cueva dentro de la excavación y mató a más de la mitad de sus guerreros. Ahora mantiene su campamento en la frontera del Desierto con una banda demasiado maltrecha para marchar. Espera órdenes de Belgrom Rockmaul en {link:orgrimmar}Orgrimmar{/link}, y vigila el sur.]=],
		},
