			text = [=[Moktar fue el primero de la {link:horde}Horda{/link} en encontrarse con los silítidos en {link:thousand-needles}las Agujas{/link}, y lo pagó caro. Su informe, llevado a Korran en {link:the-crossroads}El Cruce{/link}, ayudó a la Horda a empezar a comprender a los insectos.]=],
		},
	},
	chapters = {
		{
			title = "El enjambre crece",
			hint = "Haga retroceder a los insectos de la Excavación Oximelena.",
			text = [=[Belgrom quería que los insectos volvieran a las profundidades de las que habían salido. Los guerreros de Moktar no podían hacerlo solos. Con la ayuda de viajeros que iban a las carreras, el enjambre fue diezmado, y los caparazones tomados de los muertos se enviaron a Korran para su estudio.]=],
		},
	},
	mentions = {
