	},
})

Translate("esMX", "pozzik", {
	title = "Pozzik",
	subtitle = "Jefe de mecánicos de los corredores goblin",
	found = "Los boxes goblin del Circuito del Espejismo",
	hint = [=[Hable con el mecánico goblin en los boxes goblin del Circuito del Espejismo.]=],
	allegiance = "Cártel Bonvapor · Equipo de carreras goblin",
	sections = {
		{
			title = "Resumen",
			text = [=[Pozzik fue en otro tiempo uno de los manitas más respetados de Undermine. Dejó atrás la Unión de Manitas para trabajar en bólidos, y lo primero que hizo fue diseñar los modelos de dos motores que el equipo goblin aún conduce. Ahora dirige a sus mecánicos en {link:the-shimmering-flats}El Desierto de Sal{/link}. Pesa cada perno y cada hueso, porque en las carreras cada gramo importa.]=],
		},
		{
			title = "Importancia",
			text = [=[Pozzik es el cerebro del equipo goblin, y está perdiendo. Los gnomos le están ganando terreno, y hará casi cualquier cosa por no quedarse atrás: recurrir a los barones y constructores goblins que lo patrocinan, y robar a sus rivales si hace falta.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Diseñó los bólidos goblin de dos motores.
• Construye sus chasis con los huesos huecos de los buitres del Desierto.
• Buscó un nuevo regulador de combustible por medio de {link:gazlowe}Gazlowe{/link} de {link:ratchet}Trinquete{/link} y del barón {link:baron-revilgaz}Revilgaz{/link} de {link:booty-bay}Bahía del Botín{/link}.
• Hizo robar los planos de Rizzle Brassbolts, y descubrió en ellos el secreto del indurio.]=],
		},
		{
			title = "Sin registro",
			text = [=[Poco se ha escrito de los años de Pozzik en Undermine o de por qué los dejó.]=],
		},
	},
	chapters = {
		{
			title = "Patrocinio goblin",
			hint = [=[Averigüe qué fue del regulador de combustible prometido a Pozzik.]=],
			text = [=[{link:gazlowe}Gazlowe{/link} había prometido un nuevo regulador de combustible, y nunca llegó. El rastro iba de {link:ratchet}Trinquete{/link} a los muelles de {link:booty-bay}Bahía del Botín{/link} y al barón {link:baron-revilgaz}Revilgaz{/link}, que admitió que sus hombres no habían logrado encontrar los planos. Los planos estaban en la casa de un capataz de {link:venture-company}Ventura y Cía.{/link} en la {link:stranglethorn-vale}Vega de Tuercespina{/link}, que había montado el nuevo regulador en sus trituradoras. Cuando los planos llegaron por fin a Pozzik, no eran más que dibujos. Aun así quedó satisfecho, porque ahora podía mejorar el diseño desde cero.]=],
		},
		{
			title = "No quedarse atrás",
			hint = [=[Ayude a Pozzik a descubrir el secreto de la velocidad de los gnomos.]=],
			text = [=[Los coches gnomos se habían vuelto más rápidos, pero todos los diseños que Pozzik podía ver eran iguales que antes. Concluyó que los gnomos habían encontrado un material nuevo. Mientras Zamek provocaba una distracción, los planos de Rizzle Brassbolts le fueron sustraídos delante de sus narices. Hablaban del indurio, un mineral de la excavación enana de {link:uldaman}Uldaman{/link} que resiste un gran calor, y un trozo de él se había usado como pisapapeles.]=],
		},
	},
	mentions = {
		{ text = "Aligerar la carga" },
		{ text = "Patrocinio goblin" },
		{ text = "Patrocinio goblin, los planos traídos a casa" },
		{ text = "El decimoctavo piloto" },
		{ text = "No quedarse atrás" },
		{ text = "Los esquemas de Rizzle" },
		{ text = "Mineral de indurio" },
	},
	bonds = {
		{ id = "razzeric", name = "Razzeric", note = "el piloto del equipo" },
		{ id = "gazlowe", name = "Gazlowe", note = "un patrocinador" },
		{ id = "fizzle-brassbolts", name = "Fizzle Brassbolts", note = "un rival" },
		{ id = "race-master-kronkrider", name = "Maestro de carreras Kronkrider", note = "dirige la pista" },
	},
})

Translate("esMX", "razzeric", {
	title = "Razzeric",
	subtitle = "El decimoctavo piloto",
	found = "Los boxes goblin del Circuito del Espejismo",
	hint = [=[Hable con el piloto goblin al que le gusta más potencia de la que le conviene.]=],
	allegiance = "Equipo de carreras goblin",
	sections = {
		{
			title = "Resumen",
			text = [=[Razzeric es el piloto del equipo de carreras goblin, el decimoctavo en ocupar ese asiento. Antes hacía recados por los boxes. Ahora conduce, y cuando {link:pozzik}Pozzik{/link} termina cada bólido, Razzeric afloja los controles, aligera el chasis y le añade más fuego. Pozzik le puso un cubo de arena bajo el asiento. Razzeric no se lo perdona.]=],
		},
		{
			title = "Importancia",
			text = [=[Razzeric es la razón de que los goblins ganen cuando ganan, y la razón de que ardan cuando arden. Su propio ingeniero en {link:gadgetzan}Gadgetzan{/link} se preguntó en voz alta si el decimonoveno piloto valdría algo.]=],
		},
	},
	chapters = {
		{
			title = "La seguridad es lo primero",
			hint = "Consiga que le quiten el seguro al propulsor de Razzeric.",
			text = [=[Razzeric encargó un propulsor de seforio a {link:shreev}Shreev{/link}, del Gizmorium de {link:gadgetzan}Gadgetzan{/link}, en {link:tanaris}Tanaris{/link}. El zepelín que lo transportaba se estrelló en el {link:dustwallow-marsh}Marjal Revolcafango{/link}, y cuando por fin se encontró el propulsor, todavía llevaba puesto el seguro. Razzeric lo devolvió. Shreev, que ya lo había hecho mucho más peligroso de lo sensato, le quitó el seguro.]=],
		},
	},
	mentions = {
		{ text = "El decimoctavo piloto" },
		{ text = "Los ajustes de Razzeric" },
		{ text = "La seguridad es lo primero" },
		{ text = "La seguridad es lo primero, el propulsor devuelto" },
	},
	bonds = {
		{ id = "pozzik", name = "Pozzik", note = "su mecánico" },
	},
})

