Translate("esMX", "kravel-koalbeard", {
	title = "Kravel Koalbeard",
	subtitle = "Traficante del Circuito del Espejismo",
	found = "Junto a los boxes gnomos del Circuito del Espejismo",
	hint = [=[Hable con el traficante que compra chatarra y vende favores en el Circuito.]=],
	allegiance = "Su propia bolsa",
	aliases = { "Kravel" },
	sections = {
		{
			title = "Resumen",
			text = [=[Kravel Koalbeard se dedica a conseguir a la gente lo que necesita, y a quedarse con su parte por el camino. Compra los restos de los bólidos estrellados y se los revende al equipo que pague. Atiende los pedidos de los gnomos, y se guarda un poco de cada uno. Cree que siempre hay beneficio en la desgracia ajena, y lo dice abiertamente.]=],
		},
		{
			title = "Importancia",
			text = [=[Kravel es la cara oculta del {link:mirage-raceway}Circuito del Espejismo{/link}. Por medio de él, la rivalidad entre goblins y gnomos se convierte en un comercio de secretos, sobornos y cerveza adulterada, y su alcance va de {link:ratchet}Trinquete{/link} a {link:booty-bay}Bahía del Botín{/link}.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Compra la chatarra de los bólidos destrozados en {link:the-shimmering-flats}el Desierto{/link}.
• Se quedó un pequeño pedazo del pedido de piezas de los gnomos antes de entregarlo.
• Descubrió un secreto del piloto goblin Nazz Steamboil y pensaba vender su silencio.
• Envió una caja de munición especial a su viejo cliente {link:hemet-nesingwary}Hemet Nesingwary{/link} en {link:stranglethorn-vale}Tuercespina{/link}.]=],
		},
		{
			title = "Sin registro",
			text = [=[Poco se ha escrito de dónde vino Kravel, o de quién paga su cuenta.]=],
		},
	},
	chapters = {
		{
			title = "El secreto del piloto",
			hint = "Averigüe la verdad sobre el piloto goblin Nazz Steamboil.",
			text = [=[Kravel había oído que el piloto goblin Nazz Steamboil no siempre había llevado ese nombre. Mandó recado a {link:krazek}Krazek{/link}, el propagador de rumores de {link:booty-bay}Bahía del Botín{/link}, que pagó con favores y con una rara botella de vino élfico para averiguar el porqué. Krazek juzgó el secreto demasiado peligroso para usarlo él mismo. Kravel no. Calculó que Nazz pagaría una pequeña fortuna por mantenerlo oculto.]=],
		},
		{
			title = "La Fool's Stout",
			hint = [=[Ayude a Kravel a probar una artimaña contra los equipos de boxes.]=],
			text = [=[Con {link:crank-fizzlebub}Crank Fizzlebub{/link} de {link:booty-bay}Bahía del Botín{/link}, Kravel urdió una artimaña. Fizzlebub mezcló una cerveza negra con el brebaje que el trol {link:zanzil-the-outcast}Zanzil{/link} da a sus sirvientes sin mente, y la levadura se desbocó en ella. Kravel dio la Fool's Stout a uno de los equipos de boxes la víspera de una carrera, e hizo su apuesta. Funcionó, y esperaba más.]=],
		},
	},
	mentions = {
		{ text = "Piezas del coche cohete" },
		{ text = "El maestro del muelle Dizzywig" },
		{ text = "Piezas para Kravel" },
		{ text = "Entrega para los gnomos" },
		{ text = "El propagador de rumores" },
		{ text = "Rumores para Kravel" },
		{ text = "De vuelta a {link:booty-bay}Bahía del Botín{/link}" },
		{ text = "Emborrachar a los gnomos" },
		{ text = "Emborrachar a los goblins" },
		{ text = "Informar a {link:crank-fizzlebub}Fizzlebub{/link}" },
		{ text = "{link:hemet-nesingwary}Hemet Nesingwary{/link}" },
	},
	bonds = {
		{ id = "fizzle-brassbolts", name = "Fizzle Brassbolts", note = "un cliente al que timó" },
		{ id = "crank-fizzlebub", name = "Crank Fizzlebub", note = "su socio en artimañas" },
		{ id = "krazek", name = "Krazek", note = "le vendió un secreto" },
		{ id = "hemet-nesingwary", name = "Hemet Nesingwary", note = "un viejo cliente" },
	},
})

Translate("esMX", "race-master-kronkrider", {
	title = "Maestro de carreras Kronkrider",
	subtitle = "Señor del Circuito del Espejismo",
	found = "La tribuna del Circuito del Espejismo",
	hint = [=[Hable con el señor de la pista de carreras de El Desierto de Sal.]=],
	allegiance = "Circuito del Espejismo",
	aliases = { "Kronkrider" },
	sections = {
		{
